import classNames from 'classnames'
import {memo} from 'react'
import {Link} from 'react-router'

import Icon from '../../../../../common/Icon/Icon'
import {usePipelineId} from '../../../hooks/pipeline'
import {useIsSettingsChanged, useJobId} from '../../EditPipelinePage.hooks'
import useSaveChangesError from '../../SaveChanges/hooks/useSaveChangesError'

import styles from './PipelineTile.module.css'

function PipelineTile() {
  const pipelineId = usePipelineId()
  const selectedJob = useJobId()
  const {hasSettingsErrors} = useSaveChangesError(pipelineId)
  const isSettingsChanged = useIsSettingsChanged()
  const selected = selectedJob == null
  const statusText = selected ? 'Editing' : isSettingsChanged ? 'Edited' : null

  return (
    <Link
      className={classNames(styles.pipeline, {
        [styles.selected]: selected,
        [styles.error]: hasSettingsErrors,
      })}
      to={'?edit=true'}
      draggable={false}
    >
      <span className={styles.label}>
        <Icon name={'settings'} />
        {'Pipeline settings'}
        <span className={classNames(styles.status, {[styles.error]: hasSettingsErrors})}>
          {statusText}
        </span>
      </span>
    </Link>
  )
}

export default memo(PipelineTile)
