import scheduleRAF from '@jetbrains/ring-ui-built/components/global/schedule-raf'
import type {GraphNode as DagNode} from 'd3-dag/dist/graph'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'
import type * as React from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../hooks/react-redux'
import {emptyArray} from '../../../../../utils/empty'
import type {Point} from '../../../../../utils/geometry'
import type {ExtraEdge} from '../../components/PipelineChart/PipelineChart'
import PipelineChart from '../../components/PipelineChart/PipelineChart'
import type {pipelineHeadBuildTypeFragment$key} from '../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import {usePipelineId} from '../../hooks/pipeline'
import useMapAgentCompatibilities from '../../hooks/useMapAgentCompatibilities'
import type {GraphNode} from '../../utils/graph'
import {
  useDebugJobIdMap,
  useJobId,
  usePipelineDraftGraph,
  usePipelineExistingJobIdsSet,
} from '../EditPipelinePage.hooks'
import {useToggleDependency} from '../SettingsSidebarContent/JobSettingsSidebar/JobDependencies/JobDependencies.hooks'

import AddJob from './AddJob/AddJob'
import EditPipelineJob from './EditPipelineJob/EditPipelineJob'
import PipelineTile from './PipelineTile/PipelineTile'

import styles from './EditPipelineChart.module.css'

const NODE_HEIGHT = 88
const NODE_WIDTH = 192
const GAP_HORIZONTAL = 32
const GAP_VERTICAL = 8
const LINE_SNAP_ZONE = 4

type Props = {pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null}

export type DrawingLine = {
  source?: string
  target?: string
}

function EditPipelineChart({pipelineHeadBuildTypeKey}: Props) {
  const selectedJob = useJobId()

  const existingJobIds = usePipelineExistingJobIdsSet()
  const graph = usePipelineDraftGraph()
  const [drawingLine, setDrawingLine] = useState<DrawingLine | null>(null)
  const [drawingLineMouseDownTarget, setDrawingLineMouseDownTarget] = useState<EventTarget | null>(
    null,
  )
  const [mousePosition, setMousePosition] = useState<Point | null>(null)
  const ref = useRef<HTMLDivElement>(null)
  const schedule = useMemo(() => scheduleRAF(), [])
  const [snappedJobId, setSnappedJobId] = useState<string>()
  const dispatch = useAppDispatch()
  const pipelineId = usePipelineId()
  const [selectedEdge, setSelectedEdge] = useState<string | null>(null)
  const deletedJobs =
    useAppSelector(state => state.pipelines.pipelineDraft[pipelineId]?.deleted?.jobs) ?? emptyArray
  const {getIsCurrentAgentIncompatibleByJobId} = useMapAgentCompatibilities()
  const debugJobIdMap = useDebugJobIdMap()

  const getSnappedJobWarning = useCallback(
    (snappedId: string | null | undefined) => {
      if (drawingLine != null && snappedId != null) {
        if (deletedJobs.includes(snappedId)) {
          return `This job has been deleted`
        }
        if (snappedId === drawingLine.source || snappedId === drawingLine.target) {
          return `Can't link a job to itself`
        }
        const {dependencies, dependants, predecessors, successors} = graph[snappedId]
        if (
          (drawingLine.source != null && dependencies.has(drawingLine.source)) ||
          (drawingLine.target != null && dependants.has(drawingLine.target))
        ) {
          return `This job is already linked`
        }
        if (
          (drawingLine.source != null && successors.has(drawingLine.source)) ||
          (drawingLine.target != null && predecessors.has(drawingLine.target))
        ) {
          return `Circular dependency detected`
        }
      }

      return null
    },
    [drawingLine, graph, deletedJobs],
  )
  const getJobWarning = (jobId: string) => {
    const snappedJobWarning = jobId === snappedJobId ? getSnappedJobWarning(snappedJobId) : null

    if (snappedJobWarning == null) {
      return getIsCurrentAgentIncompatibleByJobId(jobId) ? 'No compatible agent' : null
    }

    return snappedJobWarning
  }

  const startDrawing = useCallback((line: DrawingLine, mouseDownEvent: React.MouseEvent) => {
    setDrawingLine(line)
    setDrawingLineMouseDownTarget(mouseDownEvent.target)
    setSelectedEdge(null)
  }, [])

  const toggleDependency = useToggleDependency()
  useEffect(() => {
    const container = ref.current
    if (container != null && drawingLine != null) {
      const onMouseMove = (e: MouseEvent) => {
        schedule(() => {
          const {left, top} = container.getBoundingClientRect()
          setMousePosition({x: e.clientX - left, y: e.clientY - top})
        })
      }
      document.addEventListener('mousemove', onMouseMove)
      const onMouseUp = (e: MouseEvent) => {
        if (e.target !== drawingLineMouseDownTarget) {
          setDrawingLine(null)
          setMousePosition(null)
          if (snappedJobId != null && getSnappedJobWarning(snappedJobId) == null) {
            const from = drawingLine.target != null ? drawingLine.target : snappedJobId
            const to = drawingLine.source != null ? drawingLine.source : snappedJobId
            toggleDependency(from, to, true)
            setSelectedEdge(`${to} => ${from}`)
          }
        }
        setDrawingLineMouseDownTarget(null)
      }
      document.addEventListener('mouseup', onMouseUp)
      return () => {
        document.removeEventListener('mousemove', onMouseMove)
        document.removeEventListener('mouseup', onMouseUp)
      }
    }
    return undefined
  }, [
    dispatch,
    drawingLine,
    drawingLineMouseDownTarget,
    toggleDependency,
    getSnappedJobWarning,
    graph,
    pipelineId,
    schedule,
    snappedJobId,
  ])

  const getExtraEdges = useCallback(
    (nodes: DagNode<GraphNode>[]): ExtraEdge[] => {
      if (mousePosition == null) {
        return []
      }
      const source = nodes.find(node => node.data.id === drawingLine?.source)
      const target = nodes.find(node => node.data.id === drawingLine?.target)
      const snapped = nodes.find(node => {
        const nodeX = node.y! - NODE_WIDTH / 2 - GAP_HORIZONTAL / 2
        const nodeY = node.x! - NODE_HEIGHT / 2 - GAP_VERTICAL / 2
        return (
          mousePosition.x >= nodeX - LINE_SNAP_ZONE &&
          mousePosition.x <= nodeX + NODE_WIDTH + LINE_SNAP_ZONE &&
          mousePosition.y >= nodeY - LINE_SNAP_ZONE &&
          mousePosition.y <= nodeY + NODE_HEIGHT + LINE_SNAP_ZONE
        )
      })
      const snappedId = snapped?.data.id
      setSnappedJobId(snappedId)
      const warning = getSnappedJobWarning(snappedId)
      if (source != null) {
        const pseudoTarget = snapped ?? {
          y: mousePosition.x + NODE_WIDTH / 2 + GAP_HORIZONTAL / 2,
          x: mousePosition.y + GAP_VERTICAL / 2,
        }
        return [
          {
            source,
            target: pseudoTarget,
            points: [
              [source.x, source.y],
              [pseudoTarget.x, pseudoTarget.y],
            ],
            selected: true,
            warning: warning != null,
          },
        ]
      } else if (target != null) {
        const pseudoSource = snapped ?? {
          y: mousePosition.x - NODE_WIDTH / 2 + GAP_HORIZONTAL / 2,
          x: mousePosition.y + GAP_VERTICAL / 2,
        }
        return [
          {
            source: pseudoSource,
            target,
            points: [
              [pseudoSource.x, pseudoSource.y],
              [target.x, target.y],
            ],
            selected: true,
            warning: warning != null,
          },
        ]
      } else {
        return []
      }
    },
    [mousePosition, getSnappedJobWarning, drawingLine],
  )

  return (
    <div className={styles.chart}>
      <PipelineTile />
      <PipelineChart
        containerRef={ref}
        getExtraEdges={getExtraEdges}
        graph={graph}
        nodeWidth={NODE_WIDTH}
        nodeHeight={NODE_HEIGHT}
        gapHorizontal={GAP_HORIZONTAL}
        gapVertical={GAP_VERTICAL}
        selectableEdges
        selectedEdge={selectedEdge}
        setSelectedEdge={setSelectedEdge}
        renderJob={node => {
          const {id} = node.data
          return (
            <EditPipelineJob
              x={node.y! - NODE_WIDTH / 2 - GAP_HORIZONTAL / 2}
              y={node.x! - NODE_HEIGHT / 2 - GAP_VERTICAL / 2}
              selected={selectedJob === id}
              isNew={!existingJobIds.has(id)}
              key={id}
              id={id}
              debugJobId={debugJobIdMap.get(id)}
              pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey}
              startDrawing={startDrawing}
              drawingLine={drawingLine}
              warningMessage={getJobWarning(id)}
            />
          )
        }}
        showTransitiveEdges
      />
      <AddJob />
    </div>
  )
}

export default EditPipelineChart
